@fragment fn bloomExtract(in: bloomExtract_Input) -> @location(0)  vec4f {
    let texel = 0.5 / vec2f(textureDimensions(source));
    var colour = vec3f(0.0);
    for (var y = -1; y <= 1; y += 2) {
      for (var x = -1; x <= 1; x += 2) {
        let sampleColour = textureSampleLevel(source, linear, in.uv + vec2f(f32(x), f32(y)) * texel, 0.0).rgb;
        let peak = max(sampleColour.r, max(sampleColour.g, sampleColour.b));
        let knee = pow(clamp(peak - 0.55, 0.0, 0.9), 2.0) / 1.8;
        let gain = max(peak - 1.0, knee) / max(peak, 0.0001);
        // Only soft flake emission enters here; it cannot reach the sharp resolve.
        let leafGlow = textureSampleLevel(lower, linear, in.uv + vec2f(f32(x), f32(y)) * texel, 0.0).rgb;
        colour += (sampleColour * gain + leafGlow) * 0.25;
      }
    }
    return vec4f(colour, 0.0);
  }

