struct toneAndComposite_Input {
  @location(0) uv: vec2f,
}

@fragment fn toneAndComposite(in: toneAndComposite_Input) -> @location(0)  vec4f {
    let scene = textureSampleLevel(source, linear, in.uv, 0.0);
    let halo = tent(in.uv, 1.0 / vec2f(textureDimensions(lower))).rgb * 0.15;
    // Tone-map light with zero geometric coverage separately. Its brightest display
    // channel defines coverage, so the straight halo is luminous rather than grey.
    // Dividing faint radiance by an arbitrary alpha made a dark cloud on light sheets.
    let haloDisplay = clamp(pow(halo / (vec3f(1.0) + halo * 0.22), vec3f(0.4545)), vec3f(0.0), vec3f(1.0));
    let haloAlpha = max(haloDisplay.r, max(haloDisplay.g, haloDisplay.b));
    let alpha = scene.a + haloAlpha * (1.0 - scene.a);
    if (alpha < 0.000001) { return vec4f(0.0); }
    let radiance = scene.rgb / max(scene.a, 0.000001); // Bloom never lifts opaque iron or washes out its embossed lettering.
    let display = clamp(pow(max(radiance / (vec3f(1.0) + radiance * 0.22), vec3f(0.0)), vec3f(0.4545)), vec3f(0.0), vec3f(1.0));
    var colour = display * scene.a + haloDisplay * (1.0 - scene.a);

    return vec4f(colour, alpha);
  }

struct GoldLeaf {
  position: vec4f,
  velocity: vec4f,
  shape: vec4f,
  fall: vec4f,
  travel: vec4f,
}

@group(0) @binding(0) var<storage, read> particles: array<GoldLeaf>;

struct MedalUniforms {
  viewport: vec4f,
  centre: vec4f,
  motion: vec4f,
  strike: vec4f,
  rot0: vec4f,
  rot1: vec4f,
  rot2: vec4f,
  light: vec4f,
  forge: vec4f,
  metal: vec4f,
  metalNext: vec4f,
  leaf: vec4f,
}

@group(1) @binding(0) var<uniform> frame: MedalUniforms;

fn lamp(direction: vec3f, towards: vec3f, size: f32) -> f32 {
  return exp((dot(direction, towards) - 1.0) / (size * size * 0.5));
}

struct goldLeafVertex_Output {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
  @location(1) radiance: vec3f,
  @location(2) softness: f32,
  @location(3) opacity: f32,
  @location(4) bokeh: f32,
  @location(5) seed: f32,
  @location(6) trail: f32,
  @location(7) projected: vec2f,
}

@vertex fn goldLeafVertex(@builtin(vertex_index) vertexIndex: u32, @builtin(instance_index) instanceIndex: u32) -> goldLeafVertex_Output {
  let leaf = particles[instanceIndex];
  let clock = frame.motion.w;
  let corners = array<vec2f, 6>(vec2f(-1.0,-1.0), vec2f(1.0,-1.0), vec2f(-1.0,1.0),
    vec2f(-1.0,1.0), vec2f(1.0,-1.0), vec2f(1.0,1.0));
  let corner = corners[vertexIndex % 6u];
  let piece = vertexIndex / 6u;
  let isTrail = piece < 2u;
  let rotation = leaf.shape.z + leaf.shape.w * clock;
  let tumble = leaf.position.w * 6.283185 + leaf.fall.w * clock;
  let twist = leaf.shape.z * 1.7 + clock * 0.43;
  let axisU = vec3f(cos(rotation), sin(rotation), 0.0);
  let axisV = vec3f(-sin(rotation) * cos(tumble), cos(rotation) * cos(tumble), sin(tumble));
  let normalBase = cross(axisU, axisV);
  let u = axisU * cos(twist) + normalBase * sin(twist);
  let v = axisV;
  let n = normalize(cross(u, v));
  let centre = leaf.position.xyz;
  let w = (6.9 - centre.z) / 6.9;
  let centreScreen = vec2f(centre.x, -centre.y) * frame.viewport.z / w;
  let bokeh = select(0.0, smoothstep(0.95, 1.65, centre.z), instanceIndex < 4u);
  // Project the true tumbling plane. Defocused foreground pieces expand into low-alpha discs.
  let irregular = corner * vec2f(1.0 - 0.12 * leaf.position.w * corner.y,
    1.0 + 0.09 * sin(leaf.shape.z) * corner.x);
  let local = (u * irregular.x * leaf.shape.x + v * irregular.y * leaf.shape.y) * 0.5;
  var offset = vec2f(local.x, -local.y) * frame.viewport.z / w;
  let discRadius = leaf.shape.x * frame.viewport.z / w * 1.15;
  offset = mix(offset, corner * discRadius, bokeh);
  // Two capped shutter segments curve along actual travel; the final quad is sharp foil.
  let worldVelocity = leaf.travel.xyz;
  let projectedVelocity = vec2f(worldVelocity.x + centre.x * worldVelocity.z / (6.9 - centre.z),
    -worldVelocity.y - centre.y * worldVelocity.z / (6.9 - centre.z)) * frame.viewport.z / w;
  let speed = length(projectedVelocity);
  let direction = projectedVelocity / max(speed, 0.001);
  let shutter = min(0.016, 1.5 * leaf.shape.x * frame.viewport.z / w / max(speed, 0.001))
    * max(leaf.travel.w, smoothstep(0.5, 2.0, length(leaf.velocity.xyz)));
  let blur = speed * shutter;
  var trail = 0.0;
  var depth = centre.z + local.z * (1.0 - bokeh);
  if (isTrail) {
    trail = (f32(piece) + (corner.x + 1.0) * 0.5) * 0.5;
    let age = shutter * trail;
    let omega = leaf.velocity.w / (0.65 + length(centre.xz) * 0.4);
    let acceleration = -omega * omega * vec3f(centre.x, 0.27 * centre.x + 0.42 * centre.z, centre.z);
    let previous = centre - worldVelocity * age + acceleration * age * age * 0.5;
    let previousW = (6.9 - previous.z) / 6.9;
    let previousScreen = vec2f(previous.x, -previous.y) * frame.viewport.z / previousW;
    let halfWidth = leaf.shape.y * frame.viewport.z * 0.40 / w;
    offset = previousScreen - centreScreen + vec2f(-direction.y, direction.x) * corner.y
      * halfWidth * (1.0 - 0.30 * trail);
    depth = previous.z;
  }
  let centreY = frame.centre.y + centreScreen.y;
  let below = smoothstep(frame.leaf.x - 24.0 * frame.viewport.w,
    frame.leaf.x, centreY);
  let header = 1.0 - smoothstep(frame.leaf.y + 48.0 * frame.viewport.w,
    frame.leaf.y + 80.0 * frame.viewport.w, centreY);
  let chip = smoothstep(frame.viewport.x - 84.0 * frame.viewport.w,
    frame.viewport.x - 64.0 * frame.viewport.w, frame.centre.x + centreScreen.x)
    * (1.0 - smoothstep(frame.leaf.y + 125.0 * frame.viewport.w,
      frame.leaf.y + 145.0 * frame.viewport.w, centreY));
  let quietArea = max(below, max(header, chip));
  offset *= mix(1.0, 0.38, below);
  let screen = frame.centre.xy + centreScreen + offset;
  let ndc = screen / frame.viewport.xy * vec2f(2.0, -2.0) + vec2f(-1.0, 1.0);
  let viewDirection = normalize(vec3f(0.0, 0.0, 6.9) - centre);
  let reflected = reflect(-viewDirection, n);
  let keyDirection = normalize(vec3f(-0.52, 0.60, 0.61));
  let key = lamp(reflected, keyDirection, 0.150);
  let low = lamp(reflected, normalize(vec3f(-0.10, -0.17, 0.98)), 0.130);
  let diffuse = abs(dot(n, keyDirection));
  let gold = mix(vec3f(0.58, 0.245, 0.045), vec3f(0.92, 0.64, 0.30), leaf.position.w);
  let colour = gold * (0.35 + pow(diffuse, 0.65) * 1.10)
    + vec3f(1.0, 0.89, 0.66) * (key * 24.0 + low * 28.0);
  let heat = frame.strike.x;
  let centreLight = heat * heat * 5.0 / (0.30 + dot(centre, centre))
    * (0.2 + 0.8 * abs(dot(n, normalize(-centre + vec3f(0.0001)))));
  let bright = colour + vec3f(1.0, 0.72, 0.30) * centreLight;
  let lit = mix(bright, min(bright, vec3f(0.12, 0.065, 0.025)), quietArea);
  let softness = mix(0.035, 0.12, smoothstep(0.35, 1.7, abs(centre.z)));
  let projected = (screen - frame.centre.xy) / frame.viewport.z;
  let speck = smoothstep(1.5, 3.0, leaf.shape.x * frame.viewport.z / frame.viewport.w);
  var opacity = mix(0.30, 0.92, speck) * mix(1.0, 0.16, bokeh);
  opacity *= mix(1.0, 0.18, quietArea);
  opacity *= smoothstep(frame.leaf.y, frame.leaf.y + 16.0 * frame.viewport.w, screen.y);
  if (isTrail) { opacity *= 0.30 * smoothstep(0.5, 3.0, blur / frame.viewport.w) * (1.0 - bokeh); }
  return goldLeafVertex_Output(vec4f(ndc * w, (6.9 - depth) / 12.0 * w, w), corner, lit, softness, opacity, bokeh, leaf.position.w, trail, projected);
}

struct goldLeafBloomFragment_Input {
  @location(0) uv: vec2f,
  @location(1) radiance: vec3f,
  @location(2) softness: f32,
  @location(3) opacity: f32,
  @location(4) bokeh: f32,
  @location(5) seed: f32,
  @location(6) trail: f32,
  @location(7) projected: vec2f,
}

@fragment fn goldLeafBloomFragment(in: goldLeafBloomFragment_Input) -> @location(0)  vec4f {
  // Mostly rectangular torn foil: unequal cut corners, never a capsule silhouette.
  let uv = in.uv;
  let cut = abs(uv.x + uv.y * (0.78 + in.seed * 0.24)) / 1.78;
  let rectangle = max(max(abs(uv.x), abs(uv.y)), cut);
  let edge = mix(rectangle, length(uv), in.bokeh);
  let aa = max(fwidth(edge), mix(in.softness, 0.70, in.bokeh));
  let quiet = in.projected / vec2f(0.58, 1.06);
  let quietSquared = quiet * quiet;
  let subject = exp(-dot(quietSquared, quietSquared));
  let tail = 1.0 - smoothstep(0.05, 1.0, in.trail) * 0.94;
  let foil = 1.0 - smoothstep(1.0 - aa, 1.0, edge);
  let gaussian = exp(-dot(uv, uv) * 4.5) * (1.0 - smoothstep(0.7, 1.0, length(uv)));
  // Absolutely no foreground bokeh over the face; ordinary foil fades before the numeral.
  let faceClear = smoothstep(0.08, 0.60, 1.0 - subject);
  let alpha = select(foil, gaussian, in.bokeh > 0.0) * in.opacity * faceClear * tail;
  let fold = 0.91 + 0.09 * smoothstep(-0.15, 0.15, uv.x + uv.y * 0.35);
  let radiance = in.radiance * fold;
  // Scale every channel together: the foil keeps its hue below the SDR shoulder.
  // Excess energy goes to a separate, blurred light target, never the sharp quad.
  let peak = max(radiance.r, max(radiance.g, radiance.b));
  let core = radiance * min(1.0, 0.72 / max(peak, 0.0001));
  let excess = max(radiance - core, vec3f(0.0));
  return vec4f(excess * alpha * gaussian, 0.0);
}
